	const isLifecycleScript = lifecycleEvent === "prepare" || lifecycleEvent === "postinstall";
	const root = process.cwd();
	const isFirstHooksRun = !existsSync(join(root, dir ?? ".vite-hooks", "_", "pre-commit"));
	let shouldSetupHooks = !skipHooks;
